export class SandboxResource {
  constructor(private readonly t: Transport) {}

  /**
   * Sandbox only — close a period now and run the real billing flow
   *
   * Lowers the period's cutoff to now + 5 s, then billing runs exactly as at month end: watermark (starting 30 s after
   * the new cutoff), rating, numbering (`SBX-…`) and the invoice saga with mock payments. Poll `GET /v1/invoices`.
   * `period` defaults to the current period. Live keys get 403.
   *
   * `POST /v1/sandbox/close-period`
   */
  sandboxClosePeriod(body?: SandboxClosePeriodRequest, options?: RequestOptions): Promise<BillingRun> {
    return this.t.request<BillingRun>({ method: "POST", path: `/v1/sandbox/close-period`, body, bodyKind: "json", response: "json" }, options);
  }

  /**
   * Sandbox only — choose the mock payment outcome for a customer
   *
   * `{"scenario": "declined"}` sets `pm_sandbox_declined`. Live keys get 403.
   *
   * `POST /v1/sandbox/customers/{external_id}/payment-scenario`
   */
  setPaymentScenario(externalId: string, body: SetPaymentScenarioRequest, options?: RequestOptions): Promise<Customer> {
    return this.t.request<Customer>({ method: "POST", path: `/v1/sandbox/customers/${seg(externalId)}/payment-scenario`, body, bodyKind: "json", response: "json" }, options);
  }

  /**
   * The payment scenarios of a sandbox customer
   *
   * What each pm_sandbox_* payment method does. Sandbox keys only.
   *
   * `GET /v1/sandbox/scenarios`
   */
  sandboxScenarios(options?: RequestOptions): Promise<SandboxScenariosResponse> {
    return this.t.request<SandboxScenariosResponse>({ method: "GET", path: `/v1/sandbox/scenarios`, response: "json" }, options);
  }

  /**
   * Run an invoice's payment again under a scenario
   *
   * Sets the invoice's customer to the scenario (it stays their payment method) and retries the invoice's payment. When the payment cannot run again now (paid, or in progress) the scenario is still set and `retried` is false with the reason in `retry_error`. Sandbox keys only.
   *
   * `POST /v1/sandbox/invoices/{id}/simulate`
   */
  sandboxSimulateInvoice(id: string, body: SandboxSimulateInvoiceRequest, options?: RequestOptions): Promise<SandboxSimulateInvoiceResponse> {
    return this.t.request<SandboxSimulateInvoiceResponse>({ method: "POST", path: `/v1/sandbox/invoices/${seg(id)}/simulate`, body, bodyKind: "json", response: "json" }, options);
  }
}

export class SubscriptionsResource {
  constructor(private readonly t: Transport) {}

  /**
   * Subscriptions, newest first
   *
   * `GET /v1/subscriptions`
   */
  listSubscriptions(query?: ListSubscriptionsQuery, options?: RequestOptions): Promise<ListSubscriptionsResponse> {
    return this.t.request<ListSubscriptionsResponse>({ method: "GET", path: `/v1/subscriptions`, query, response: "json" }, options);
  }

  /**
   * Subscribe a customer to a plan version (at most one overlapping subscription per customer)
   *
   * `POST /v1/subscriptions`
   */
  createSubscription(body: CreateSubscriptionRequest, options?: RequestOptions): Promise<Subscription> {
    return this.t.request<Subscription>({ method: "POST", path: `/v1/subscriptions`, body, bodyKind: "json", response: "json" }, options);
  }

  /**
   * One subscription with its state
   *
   * `GET /v1/subscriptions/{id}`
   */
  getSubscription(id: string, options?: RequestOptions): Promise<Subscription> {
    return this.t.request<Subscription>({ method: "GET", path: `/v1/subscriptions/${seg(id)}`, response: "json" }, options);
  }

  /**
   * End a subscription (now, or at end_time)
   *
   * With credit_unused=true the fee paid in advance for the rest of the current period is credited to the customer's balance (for a subscription billed in advance that Payrudder runs, ended now, without a coupon). The response is always {subscription, credited_minor}; credited_minor is "0" when nothing was credited.
   *
   * `DELETE /v1/subscriptions/{id}`
   */
  cancelSubscription(id: string, query?: CancelSubscriptionQuery, options?: RequestOptions): Promise<CancelSubscriptionResponse> {
    return this.t.request<CancelSubscriptionResponse>({ method: "DELETE", path: `/v1/subscriptions/${seg(id)}`, query, response: "json" }, options);
  }

  /**
   * Stop the fixed fee until the subscription is resumed (usage is still billed)
   *
   * `POST /v1/subscriptions/{id}/pause`
   */
  pauseSubscription(id: string, options?: RequestOptions): Promise<Subscription> {
    return this.t.request<Subscription>({ method: "POST", path: `/v1/subscriptions/${seg(id)}/pause`, response: "json" }, options);
  }

  /**
   * Resume a paused subscription
   *
   * `POST /v1/subscriptions/{id}/resume`
   */
  resumeSubscription(id: string, options?: RequestOptions): Promise<Subscription> {
    return this.t.request<Subscription>({ method: "POST", path: `/v1/subscriptions/${seg(id)}/resume`, response: "json" }, options);
  }

  /**
   * End the subscription at the end of its current billing period
   *
   * `POST /v1/subscriptions/{id}/cancel-at-period-end`
   */
  scheduleCancellation(id: string, options?: RequestOptions): Promise<Subscription> {
    return this.t.request<Subscription>({ method: "POST", path: `/v1/subscriptions/${seg(id)}/cancel-at-period-end`, response: "json" }, options);
  }

  /**
   * Withdraw a scheduled cancellation
   *
   * `DELETE /v1/subscriptions/{id}/cancel-at-period-end`
   */
  withdrawCancellation(id: string, options?: RequestOptions): Promise<Subscription> {
    return this.t.request<Subscription>({ method: "DELETE", path: `/v1/subscriptions/${seg(id)}/cancel-at-period-end`, response: "json" }, options);
  }

  /**
   * Move the subscription to another plan version now, prorating the fixed fee
   *
   * `POST /v1/subscriptions/{id}/change-plan`
   */
  changePlan(id: string, body: ChangePlanRequest, options?: RequestOptions): Promise<ChangePlanResponse> {
    return this.t.request<ChangePlanResponse>({ method: "POST", path: `/v1/subscriptions/${seg(id)}/change-plan`, body, bodyKind: "json", response: "json" }, options);
  }

  /**
   * What a change of plan or interval would cost, without making it
   *
   * The same calculation as the change itself, so the preview is what is then billed. For subscriptions whose fee is invoiced in advance.
   *
   * `POST /v1/subscriptions/{id}/change-preview`
   */
  previewSubscriptionChange(id: string, body: ChangeRequest, options?: RequestOptions): Promise<ChangeQuote> {
    return this.t.request<ChangeQuote>({ method: "POST", path: `/v1/subscriptions/${seg(id)}/change-preview`, body, bodyKind: "json", response: "json" }, options);
  }

  /**
   * Move a subscription to another plan version and/or interval, now or at the end of the paid period
   *
   * An upgrade or monthly-to-yearly change is immediate and prorated; a downgrade or yearly-to-monthly change waits for the end of the period the customer has paid for
   * (a scheduled change, shown on the subscription). A change of `quantity` alone is immediate and prorated, more seats or fewer. Whatever moves money is invoiced, or becomes a credit balance when the new plan costs less than the unused old time was worth.
   * Answers 409 `ABORTED` if the fee of the current period has not been invoiced yet; try again in a moment.
   *
   * `POST /v1/subscriptions/{id}/change`
   */
  changeSubscription(id: string, body: ChangeRequest, options?: RequestOptions): Promise<ChangeSubscriptionResponse> {
    return this.t.request<ChangeSubscriptionResponse>({ method: "POST", path: `/v1/subscriptions/${seg(id)}/change`, body, bodyKind: "json", response: "json" }, options);
  }

  /**
   * Redeem a coupon on a subscription that has none
   *
   * A coupon takes something off a fixed fee Payrudder invoices in advance. A subscription a provider renews uses a discount at the provider instead.
   *
   * `POST /v1/subscriptions/{id}/coupon`
   */
  applyCoupon(id: string, body: ApplyCouponRequest, options?: RequestOptions): Promise<Subscription> {
    return this.t.request<Subscription>({ method: "POST", path: `/v1/subscriptions/${seg(id)}/coupon`, body, bodyKind: "json", response: "json" }, options);
  }

  /**
   * Take the coupon off a subscription (the redemption is not given back)
   *
   * `DELETE /v1/subscriptions/{id}/coupon`
   */
  removeCoupon(id: string, options?: RequestOptions): Promise<Subscription> {
    return this.t.request<Subscription>({ method: "DELETE", path: `/v1/subscriptions/${seg(id)}/coupon`, response: "json" }, options);
  }

  /**
   * Withdraw the change waiting for the end of the period
   *
   * `DELETE /v1/subscriptions/{id}/scheduled-change`
   */
  cancelScheduledChange(id: string, options?: RequestOptions): Promise<Subscription> {
    return this.t.request<Subscription>({ method: "DELETE", path: `/v1/subscriptions/${seg(id)}/scheduled-change`, response: "json" }, options);
  }
}

