export class WebhookEndpointsResource {
  constructor(private readonly t: Transport) {}

  /**
   * The tenant's webhook endpoints
   *
   * Not paged: the response is the complete list.
   *
   * `GET /v1/webhook-endpoints`
   */
  listWebhookEndpoints(options?: RequestOptions): Promise<ListWebhookEndpointsResponse> {
    return this.t.request<ListWebhookEndpointsResponse>({ method: "GET", path: `/v1/webhook-endpoints`, response: "json" }, options);
  }

  /**
   * Register an HTTPS endpoint that receives Payrudder's events
   *
   * Payrudder sends a signed JSON POST to the endpoint for each event of the types it asks for (all types if none). The response carries the signing secret, once; it cannot be read again, only rotated. Verify each delivery with the `Payrudder-Signature` header: `t=<unix seconds>,v1=<hex HMAC-SHA256 of "<t>.<raw body>" with the secret>` (two `v1` while a rotated secret is still accepted); reject a timestamp more than five minutes from your clock. Answer 2xx within 10 seconds; anything else is retried after 1 minute, 5 minutes, 30 minutes, 2 hours, 6 hours and 24 hours, then given up (a delivery can be sent again by hand). Events are delivered at least once and not in order: use the event `id` to ignore repeats. The URL must be https and public; at most 20 endpoints.
   *
   * `POST /v1/webhook-endpoints`
   */
  createWebhookEndpoint(body: CreateWebhookEndpointRequest, options?: RequestOptions): Promise<WebhookEndpoint> {
    return this.t.request<WebhookEndpoint>({ method: "POST", path: `/v1/webhook-endpoints`, body, bodyKind: "json", response: "json" }, options);
  }

  /**
   * Replace an endpoint's url, description, event types and active flag
   *
   * `PUT /v1/webhook-endpoints/{id}`
   */
  updateWebhookEndpoint(id: string, body: WebhookEndpointInput, options?: RequestOptions): Promise<WebhookEndpoint> {
    return this.t.request<WebhookEndpoint>({ method: "PUT", path: `/v1/webhook-endpoints/${seg(id)}`, body, bodyKind: "json", response: "json" }, options);
  }

  /**
   * Delete an endpoint and its delivery history
   *
   * `DELETE /v1/webhook-endpoints/{id}`
   */
  deleteWebhookEndpoint(id: string, options?: RequestOptions): Promise<void> {
    return this.t.request<void>({ method: "DELETE", path: `/v1/webhook-endpoints/${seg(id)}`, response: "none" }, options);
  }

  /**
   * Make a new signing secret (returned once); the old one keeps signing for 24 hours
   *
   * `POST /v1/webhook-endpoints/{id}/rotate-secret`
   */
  rotateWebhookSecret(id: string, options?: RequestOptions): Promise<WebhookEndpoint> {
    return this.t.request<WebhookEndpoint>({ method: "POST", path: `/v1/webhook-endpoints/${seg(id)}/rotate-secret`, response: "json" }, options);
  }

  /**
   * Send a ping event to one endpoint
   *
   * `POST /v1/webhook-endpoints/{id}/test`
   */
  sendTestWebhook(id: string, options?: RequestOptions): Promise<WebhookDelivery> {
    return this.t.request<WebhookDelivery>({ method: "POST", path: `/v1/webhook-endpoints/${seg(id)}/test`, response: "json" }, options);
  }
}
